rss.channel:
{{ .Site.Title }} — La Corriente
{{ .Permalink }}
{{ .Site.Params.description }}
es-CL

{{ with .Site.Params.email }}{{ . }}{{ end }}
{{ with .Site.Params.author }}{{ . }} ({{ $.Site.Params.email }}){{ end }}
{{ if hugo.Data.faust }}
  {{ $sources := hugo.Data.faust.sources }}
  {{ $srcName := dict }}
  {{/* Mapa id → nombre para legibilidad */}}
  {{ range $sources }}{{ $srcName = merge $srcName (dict .id .name) }}{{ end }}

  {{ $items := hugo.Data.faust.items }}
  {{ range first 100 (sort $items "date" "desc") }}


      {{ .title }}
      {{ .link }}
      {{ .id }}
      {{ time.Format "Mon, 02 Jan 2006 15:04:05 -0700" .date }}
      {{ .category }}
      {{ with .summary }}{{ . }}{{ end }}{{ with .author }} — {{ . }}{{ end }}
      {{ with .image }}{{ end }}
      {{ index $srcName .source }}

  {{ end }}
{{ end }}
